import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';

// The pages under docs/ are generated by scripts/sync-docs.mjs from the Sirio repository; the
// sidebar lists them by slug, and Starlight takes each label from the page title, per locale.
// The features page is written here, like the home page.
export default defineConfig({
	site: 'https://siriosysadm.in',
	integrations: [
		starlight({
			title: 'Sirio SysAdmin',
			description:
				'Self-hosted web panel for running a single Linux server: Docker, deploys, domains with automatic HTTPS, backups and system updates.',
			logo: { src: './src/assets/logo.svg' },
			favicon: '/favicon.svg',
			defaultLocale: 'root',
			locales: {
				root: { label: 'English', lang: 'en' },
				it: { label: 'Italiano', lang: 'it' },
			},
			components: {
				Hero: './src/components/Hero.astro',
				SocialIcons: './src/components/HeaderLinks.astro',
			},
			// Dark by default. Starlight falls back to the system theme when nothing is stored, and
			// stores "auto" as an empty value, so seed "dark" once, on the first visit only: whoever
			// then picks Auto or Light keeps it. Runs in <head>, before Starlight's theme script.
			head: [
				{
					tag: 'script',
					content:
						"try{if(!localStorage.getItem('sirio-theme-seeded')){localStorage.setItem('sirio-theme-seeded','1');if(!localStorage.getItem('starlight-theme'))localStorage.setItem('starlight-theme','dark')}}catch{}",
				},
			],
			customCss: [
				// The width axis too: the home page sets its headlines expanded.
				'@fontsource-variable/archivo/wdth.css',
				'@fontsource-variable/jetbrains-mono',
				'./src/styles/custom.css',
			],
			sidebar: [
				'features',
				{
					label: 'Getting started',
					translations: { it: 'Per iniziare' },
					items: ['docs/installation', 'docs/updates'],
				},
				{
					label: 'Sites and deploys',
					translations: { it: 'Siti e deploy' },
					items: ['docs/domains', 'docs/pipeline', 'docs/backups', 'docs/sftp', 'docs/image-updates'],
				},
				{
					label: 'The server',
					translations: { it: 'Il server' },
					items: ['docs/packages', 'docs/security'],
				},
			],
		}),
	],
});
